#include "jp8000.h"
#include "json.hpp"
#include <array>
#include <fstream>
#include <chrono>
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <vector>
using Json=nlohmann::json;
int main(int argc,char**argv){if(argc!=4)return 2;char error[2048]{};auto start=std::chrono::steady_clock::now();auto*h=jp8000_create(argv[1],argv[2],error,sizeof(error));if(!h)throw std::runtime_error(error);auto check=[&](int r){if(r)throw std::runtime_error(jp8000_last_error(h));};auto snapshot=[&](){auto n=jp8000_snapshot_json(h,nullptr,0);std::vector<char>b(n);if(!n||jp8000_snapshot_json(h,b.data(),n)!=n)throw std::runtime_error("snapshot failure");return Json::parse(b.data());};std::array<float,128>l{},r{};auto render=[&](unsigned frames){double peak=0;for(unsigned i=0;i<frames;i+=128){auto n=std::min(128u,frames-i);check(jp8000_render(h,l.data(),r.data(),n));for(unsigned k=0;k<n;++k){if(!std::isfinite(l[k])||!std::isfinite(r[k]))throw std::runtime_error("nonfinite PCM");peak=std::max({peak,std::abs(double(l[k])),std::abs(double(r[k]))});}}return peak;};auto settle=[&](){for(unsigned i=0;i<50;++i){render(8820);jp8000_stats_t s{};check(jp8000_stats(h,&s));if(!s.state_syncing)return;}throw std::runtime_error("state readback timeout");};Json report={{"boot_seconds",std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()},{"boot",snapshot()}};
struct Change{jp8000_scope scope;unsigned wire,value,width,id;const char*part;};const Change changes[]={{JP8000_PATCH_UPPER,256,179,2,256,"params_upper"},{JP8000_PATCH_LOWER,41,77,1,41,"params_lower"},{JP8000_PART_UPPER,2,5,1,1002,"params_upper"},{JP8000_PART_LOWER,2,9,1,1002,"params_lower"},{JP8000_PERFORMANCE,34,177,2,2034,"params_upper"},{JP8000_SYSTEM,10,60,1,3010,"params_upper"}};
auto old=snapshot();for(auto c:changes)check(jp8000_parameter(h,c.scope,c.wire,c.value,c.width));if(jp8000_save_state(h,nullptr,0))throw std::runtime_error("stale state saved");bool complete=false;unsigned coherentChecks=0;for(unsigned i=0;i<3500;++i){render(128);auto view=snapshot();bool before=true,after=true;for(auto c:changes){auto key=std::to_string(c.id);before=before&&(view[c.part][key]==old[c.part][key]);after=after&&(view[c.part][key]==c.value);}if(!before&&!after)throw std::runtime_error("mixed firmware state snapshot");++coherentChecks;jp8000_stats_t st{};check(jp8000_stats(h,&st));if(!st.state_syncing){complete=true;break;}}if(!complete)throw std::runtime_error("coherent state timeout");report["coherent_snapshot_checks"]=coherentChecks;auto s=snapshot();for(auto c:changes)if(s[c.part][std::to_string(c.id)]!=c.value)throw std::runtime_error("parameter mismatch");report["six_region_changes"]=s;auto n=jp8000_save_state(h,nullptr,0);if(n!=625)throw std::runtime_error("state size");std::vector<uint8_t>saved(n);if(jp8000_save_state(h,saved.data(),n)!=n)throw std::runtime_error("save failed");for(auto c:changes)check(jp8000_parameter(h,c.scope,c.wire,c.value-1,c.width));settle();check(jp8000_load_state(h,saved.data(),saved.size()));settle();s=snapshot();for(auto c:changes)if(s[c.part][std::to_string(c.id)]!=c.value)throw std::runtime_error("restore mismatch");std::vector<uint8_t>restored(n);if(jp8000_save_state(h,restored.data(),n)!=n||restored!=saved)throw std::runtime_error("full state differs after restore");report["restore_byte_exact"]=true;report["state_bytes"]=n;
check(jp8000_factory_patch(h,127,1));settle();report["patch127"]=snapshot();check(jp8000_factory_performance(h,63));settle();report["performance63"]=snapshot();check(jp8000_panel(h,80,1));check(jp8000_panel(h,80,0));jp8000_stats_t pending{};check(jp8000_stats(h,&pending));if(!pending.state_syncing)throw std::runtime_error("panel release not serviced");settle();report["panel"]=snapshot();
for(unsigned note:{48,52,55,59,60,64,67,71})check(jp8000_midi(h,0x90,note,100,0));jp8000_stats_t before{},after{};check(jp8000_stats(h,&before));start=std::chrono::steady_clock::now();report["peak"]=render(88200);double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();check(jp8000_stats(h,&after));report["native_render_seconds"]=seconds;report["realtime_factor"]=1.0/seconds;report["aot_hits"]=after.aot_hits-before.aot_hits;report["fallbacks"]=after.aot_fallbacks-before.aot_fallbacks;check(jp8000_panic(h));settle();for(unsigned status:{0xf1,0xf2,0xf3,0xf6,0xf8,0xfa,0xfb,0xfc,0xfe})check(jp8000_midi(h,status,0,0,0));check(jp8000_midi(h,0xf8,255,255,0));check(jp8000_midi(h,0xf3,0,255,0));check(jp8000_midi(h,0xd0,0,255,0));for(unsigned status:{0x70,0xf0,0xf4,0xf5,0xf7,0xf9,0xfd,0xff})if(jp8000_midi(h,status,0,0,0)==0)throw std::runtime_error("invalid MIDI status accepted");if(jp8000_midi(h,0xf2,128,0,0)==0||jp8000_midi(h,0x90,60,128,0)==0)throw std::runtime_error("invalid MIDI data accepted");render(8820);report["system_midi_validation"]=true;jp8000_destroy(h);std::ofstream(argv[3])<<report.dump(2)<<'\n';std::cout<<"PASS state625byteexact, nativefactor="<<1.0/seconds<<'\n';}
